    // ── decimal sample literals fit tightly-scaled columns (issue #1038) ────

    #[test]
    fn decimal_literal_at_scale_never_reaches_one() {
        // Every sample literal must stay strictly under `1` for scale >= 1,
        // so it fits even the tightest valid column (`decimal{scale,scale}`,
        // whose range is `(-1,1)`) regardless of how large `precision` is.
        for scale in 1..=6 {
            for digit in [1, 2, 3] {
                let literal = decimal_literal_at_scale(scale, digit);
                let value: f64 = literal.parse().unwrap();
                assert!(
                    value.abs() < 1.0,
                    "decimal_literal_at_scale({scale}, {digit}) = {literal} must be < 1"
                );
            }
        }
    }

    #[test]
    fn decimal_sample_literals_are_pairwise_distinct_at_every_scale() {
        for scale in 0..=6 {
            let a = sql_sample_literal(FieldKind::Decimal {
                precision: scale.max(1) + 1,
                scale,
            });
            let b = unique_sample_literal(FieldKind::Decimal {
                precision: scale.max(1) + 1,
                scale,
            });
            let c = unique_sample_literal_variant(FieldKind::Decimal {
                precision: scale.max(1) + 1,
                scale,
            });
            assert!(a != b && b != c && a != c, "scale {scale}: {a}, {b}, {c}");
        }
    }

    #[test]
    fn json_sample_literals_are_pairwise_distinct_and_valid_jsonb() {
        let a = sql_sample_literal(FieldKind::Json);
        let b = unique_sample_literal(FieldKind::Json);
        let c = unique_sample_literal_variant(FieldKind::Json);
        assert!(a != b && b != c && a != c, "{a}, {b}, {c}");
        for literal in [&a, &b, &c] {
            assert!(
                literal.ends_with("'::jsonb"),
                "must be a jsonb-cast SQL literal: {literal}"
            );
            let inner = literal
                .trim_start_matches('\'')
                .trim_end_matches("'::jsonb");
            assert!(
                serde_json::from_str::<serde_json::Value>(inner).is_ok(),
                "{literal} must contain valid JSON"
            );
        }
    }

    #[test]
    fn json_seed_value_varies_per_row_for_unique_columns() {
        // Issue #1341 review: a constant `'{}'::jsonb` for every row (the
        // `sql_sample_literal` fallback) would collide on the very first
        // re-insert for a `unique` json column in the `--api` smoke test's
        // 25-row (`API_SMOKE_TEST_SEED_ROWS`) seed — must vary with `g`, same
        // as the text/numeric/timestamp arms.
        let f = csv_test_field("config", FieldKind::Json, false);
        let expr = sql_seed_value_expr(&f);
        assert!(
            expr.contains(" g "),
            "must vary per row via the generate_series index: {expr}"
        );
        assert!(
            expr.ends_with("::jsonb"),
            "must be a jsonb-cast expression: {expr}"
        );
        assert!(
            serde_json::from_str::<serde_json::Value>("{\"seed\": 1}").is_ok(),
            "sanity: the woven shape is valid JSON"
        );
    }

    #[test]
    fn enum_rejection_insert_sql_fits_tightly_scaled_decimal_column() {
        // Regression test: a `decimal{1,1}` column (valid range `(-1,1)`)
        // combined with a required enum column used to get a fixed "1.0"
        // sample literal from `sql_sample_literal`, which Postgres's
        // `NUMERIC(1,1)` rejects as a numeric field overflow — breaking a
        // generated test that has nothing to do with the enum behavior it's
        // meant to exercise.
        let status = Field {
            name: "status".to_string(),
            kind: FieldKind::Enum,
            nullable: false,
            variants: vec!["a".to_string(), "b".to_string()],
            unique: false,
            constraints: FieldConstraints::default(),
            state_machine: None,
        };
        let weight = Field {
            name: "weight".to_string(),
            kind: FieldKind::Decimal {
                precision: 1,
                scale: 1,
            },
            nullable: false,
            variants: Vec::new(),
            unique: false,
            constraints: FieldConstraints::default(),
            state_machine: None,
        };
        let fields = vec![status.clone(), weight];
        let sql = enum_rejection_insert_sql("items", &fields, &status, &BTreeMap::new());
        assert!(
            sql.contains("weight) VALUES ('__not_a_real_variant__', 0.1)"),
            "expected a scale-fitting 0.1 literal for NUMERIC(1,1), got: {sql}"
        );
    }

